// Home Administration copy. One Home, one explicit administrator, one honest
// account of what can and cannot be done right now.
//
// Two vocabulary rules are load-bearing and must survive translation:
// the reversible hold is "Disabled" with a "Re-enable" action, and the terminal
// state is "Retired" and is never offered a way back. Never promise a cause or
// timestamp for either; neither is stored.

